#include <iostream>
#include <stack>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n + 1), rg(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        rg[v].push_back(u);
    }
    vector<int> vis(n + 1, 0), order, scc(n + 1, 0);
    function<void(int)> dfs1 = [&](int u) {
        vis[u] = 1;
        for (int v : g[u])
            if (!vis[v]) dfs1(v);
        order.push_back(u);
    };
    function<void(int,int)> dfs2 = [&](int u, int id) {
        scc[u] = id;
        for (int v : rg[u])
            if (!scc[v]) dfs2(v, id);
    };
    for (int i = 1; i <= n; i++)
        if (!vis[i]) dfs1(i);
    reverse(order.begin(), order.end());
    int cnt = 0;
    for (int u : order)
        if (!scc[u]) dfs2(u, ++cnt);
    cout << cnt << endl;
    for (int i = 1; i <= n; i++) cout << scc[i] << " ";
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int,int>>> g(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v, id = i + 1;
        cin >> u >> v;
        g[u].push_back({v, id});
        g[v].push_back({u, id});
    }
    vector<int> dfn(n + 1, 0), low(n + 1, 0);
    vector<bool> isBridge(m + 1, false);
    int timer = 0;
    function<void(int,int)> dfs = [&](int u, int pe) {
        dfn[u] = low[u] = ++timer;
        for (auto [v, id] : g[u]) {
            if (id == pe) continue;
            if (!dfn[v]) {
                dfs(v, id);
                low[u] = min(low[u], low[v]);
                if (low[v] > dfn[u]) isBridge[id] = true;
            } else {
                low[u] = min(low[u], dfn[v]);
            }
        }
    };
    for (int i = 1; i <= n; i++)
        if (!dfn[i]) dfs(i, 0);
    int cnt = 0;
    for (int i = 1; i <= m; i++)
        if (isBridge[i]) cnt++;
    cout << cnt << endl;
    return 0;
}

