    }
    vector<int> dfn(n + 1, 0), low(n + 1, 0);
    vector<bool> isCut(n + 1, false);
    int timer = 0;
    function<void(int,int)> dfs = [&](int u, int p) {
        dfn[u] = low[u] = ++timer;
        int child = 0;
        for (int v : g[u]) {
            if (v == p) continue;
            if (!dfn[v]) {
                dfs(v, u);
                low[u] = min(low[u], low[v]);
                if (low[v] >= dfn[u] && p != 0) isCut[u] = true;
                child++;
            } else {
                low[u] = min(low[u], dfn[v]);
            }
        }
        if (p == 0 && child >= 2) isCut[u] = true;
    };
    for (int i = 1; i <= n; i++)
        if (!dfn[i]) dfs(i, 0);
    int cnt = 0;
    for (int i = 1; i <= n; i++)
        if (isCut[i]) cnt++;
    cout << cnt << endl;
    return 0;
}

