int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    vector<int> dfn(n + 1, 0), low(n + 1, 0), ebcc(n + 1, 0);
    vector<vector<int>> bridges;
    int timer = 0, ebccCnt = 0;
    function<void(int,int)> dfs = [&](int u, int pe) {
        dfn[u] = low[u] = ++timer;
        for (int v : g[u]) {
            if (v == pe) continue;
            if (!dfn[v]) {
                dfs(v, u);
                low[u] = min(low[u], low[v]);
                if (low[v] > dfn[u]) bridges.push_back({u, v});
            } else {
                low[u] = min(low[u], dfn[v]);
            }
        }
    };
    for (int i = 1; i <= n; i++)
        if (!dfn[i]) dfs(i, 0);
    vector<int> p(n + 1);
    for (int i = 1; i <= n; i++) p[i] = i;
    function<int(int)> find = [&](int x) { return p[x] == x ? x : p[x] = find(p[x]); };
    for (int u = 1; u <= n; u++)
        for (int v : g[u])
            if (dfn[u] < dfn[v] && low[v] > dfn[u] == false)
                p[find(u)] = find(v);
    for (int i = 1; i <= n; i++)
        if (find(i) == i) ebccCnt++;
    cout << ebccCnt << endl;
    return 0;
}

#include <iostream>
#include <stack>
#include <vector>
using namespace std;

const int N = 100005;
vector<int> adj[N];
bool used[N];
int n, m;

void dfs(int u, vector<int>& path) {
    for (int& i = 0; i < (int)adj[u].size(); i++) {
        int v = adj[u][i];
        if (!used[v]) {
            used[v] = true;
            dfs(v, path);
        }
    }
    path.push_back(u);
}

int main() {
    cin >> n >> m;
    for (int i = 1; i <= m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    int odd = 0, start = 1;
    for (int i = 1; i <= n; i++) {
        if (adj[i].size() % 2 == 1) {
            odd++;
            start = i;
        }
    }

    if (odd > 2) {
        cout << "No Euler path" << endl;
        return 0;
    }

    vector<int> path;
    dfs(start, path);

    if ((int)path.size() != m + 1) {
        cout << "Not connected" << endl;
        return 0;
    }

    for (int i = path.size() - 1; i >= 0; i--) {
        cout << path[i] << " ";
    }
    cout << endl;

    return 0;
}

