#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int N = 20, INF = 1e9;
int g[N][N], dp[1 << N][N], n, m;

int hamiltonianPath() {
    for (int i = 0; i < (1 << n); i++) {
        for (int j = 0; j < n; j++) {
            dp[i][j] = INF;
        }
    }
    for (int i = 0; i < n; i++) dp[1 << i][i] = 0;

    for (int mask = 1; mask < (1 << n); mask++) {
        for (int u = 0; u < n; u++) {
            if (!(mask & (1 << u))) continue;
            for (int v = 0; v < n; v++) {
                if (mask & (1 << v)) continue;
                dp[mask | (1 << v)][v] = min(dp[mask | (1 << v)][v], dp[mask][u] + g[u][v]);
            }
        }
    }

    int ans = INF;
    for (int i = 0; i < n; i++) {
        ans = min(ans, dp[(1 << n) - 1][i]);
    }

    return ans;
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            g[i][j] = INF;
        }
        g[i][i] = 0;
    }

    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        u--; v--;
        g[u][v] = min(g[u][v], w);
        g[v][u] = min(g[v][u], w);
    }

    int ans = hamiltonianPath();

    if (ans >= INF) {
        cout << "No Hamiltonian path" << endl;
    } else {
        cout << ans << endl;
    }

    return 0;
}
